package com.musteritakipcrm.alarm;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.security.MessageDigest;import java.text.SimpleDateFormat;import java.util.*;

public class MainActivity extends Activity{
 private static final String PREF="crm_alarm",M2="\u2063\u200B",M3="\u2063\u200C"; private LinearLayout body,list; private int page=1; private boolean archive=false,n3Unlocked=false; private String calendarDay=""; private List<Api.Entry> cache=new ArrayList<>(); private final Set<Integer> open=new HashSet<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);AlarmRingingService.ensureChannels(this);requestPermissionsIfNeeded();setContentView(ui());if(token().isEmpty())pairDialog();else{startServiceNow();load();}}
 private LinearLayout ui(){LinearLayout root=v();root.setBackgroundColor(Color.rgb(247,249,251));TextView h=t("📝 AJANDAM",21,true);h.setGravity(Gravity.CENTER);h.setPadding(18,15,18,15);h.setBackgroundColor(Color.rgb(255,202,40));root.addView(h,new LinearLayout.LayoutParams(-1,-2));body=v();body.setPadding(8,6,8,8);root.addView(body,new LinearLayout.LayoutParams(-1,-1));buildPage();return root;}
 private void buildPage(){body.removeAllViews();LinearLayout nav=new LinearLayout(this);String[] names={"NOT 1","NOT 2","🔒 NOT 3","📅 TAKVİM"};for(int i=0;i<4;i++){final int p=i+1;Button b=new Button(this);b.setText(names[i]);b.setTextSize(11);b.setOnClickListener(x->openPage(p));nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}body.addView(nav);LinearLayout tools=new LinearLayout(this);Button add=new Button(this);add.setText("+ YENİ");add.setOnClickListener(x->{if(connected())editForm(null,page==4?1:page,calendarDay);});Button arc=new Button(this);arc.setText(archive?"✓ ARŞİV":"ARŞİV");arc.setOnClickListener(x->{archive=!archive;buildPage();if(page==4)renderCalendar();else render(cache);});tools.addView(add,new LinearLayout.LayoutParams(0,-2,1));tools.addView(arc,new LinearLayout.LayoutParams(0,-2,1));body.addView(tools);if(page==4){renderCalendar();return;}ScrollView sc=new ScrollView(this);list=v();sc.addView(list);body.addView(sc,new LinearLayout.LayoutParams(-1,0,1));if(token().isEmpty())pairDialog();else render(cache);}
 private void openPage(int p){if(p==3&&!n3Unlocked){pinDialog();return;}if(page==3&&p!=3)n3Unlocked=false;page=p;archive=false;buildPage();if(p!=4)load();else if(cache.isEmpty())load();}
 private String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());} private boolean visibleMain(Api.Entry e){return !e.archived()||e.date.compareTo(today())>=0;} private boolean visibleArchive(Api.Entry e){return e.archived()&&e.date.compareTo(today())<0;}
 private void render(List<Api.Entry> all){if(list==null)return;list.removeAllViews();int n=0;for(Api.Entry e:all){if(cat(e)!=page)continue;if(archive?!visibleArchive(e):!visibleMain(e))continue;n++;list.addView(entryRow(e),rowParams());}if(n==0)list.addView(t(archive?"Arşiv boş.":"Henüz kayıt yok.",14,false));}
 private View entryRow(Api.Entry e){LinearLayout outer=v();GradientDrawable bg=new GradientDrawable();int[] colors={Color.rgb(255,249,196),Color.rgb(225,245,254),Color.rgb(232,245,233),Color.rgb(252,228,236),Color.rgb(237,231,246),Color.rgb(255,243,224)};bg.setColor(colors[Math.abs(e.id)%colors.length]);bg.setCornerRadius(12);bg.setStroke(2,Color.rgb(165,175,185));outer.setBackground(bg);outer.setPadding(4,3,6,3);LinearLayout top=new LinearLayout(this);top.setOrientation(LinearLayout.HORIZONTAL);top.setGravity(Gravity.CENTER_VERTICAL);CheckBox done=new CheckBox(this);done.setChecked(e.archived());done.setPadding(0,0,0,0);done.setOnClickListener(x->archive(e,done.isChecked()));top.addView(done,new LinearLayout.LayoutParams(-2,-2));TextView title=t(titleOf(e.note),16,true);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setOnClickListener(x->{if(open.contains(e.id))open.remove(e.id);else open.add(e.id);render(cache);});top.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView day=t(dayMonth(e.date),12,true);day.setGravity(Gravity.CENTER);top.addView(day,new LinearLayout.LayoutParams(-2,-2));TextView alarm=t(e.remindAt.isEmpty()?"":("  ⏰ "+timeOnly(e.remindAt)),12,true);alarm.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);top.addView(alarm,new LinearLayout.LayoutParams(-2,-2));outer.addView(top);if(open.contains(e.id)){String d=detailOf(e.note);if(!d.isEmpty()){TextView desc=t(d,13,false);desc.setPadding(42,5,6,5);outer.addView(desc);}LinearLayout acts=new LinearLayout(this);acts.setGravity(Gravity.RIGHT);Button edit=new Button(this);edit.setText("DÜZENLE");edit.setTextSize(10);edit.setOnClickListener(x->editForm(e,cat(e),""));Button del=new Button(this);del.setText("SİL");del.setTextSize(10);del.setOnClickListener(x->delete(e));acts.addView(edit);acts.addView(del);outer.addView(acts);}return outer;}
 private String dayMonth(String d){try{return new SimpleDateFormat("dd.MM",Locale.US).format(new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(d));}catch(Exception x){return d;}} private String timeOnly(String r){int p=r.indexOf(' ');return p>=0?r.substring(p+1):r;} private LinearLayout.LayoutParams rowParams(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,3,0,3);return p;}
 private void editForm(Api.Entry e,int category,String forcedDay){LinearLayout form=v();form.setPadding(22,3,22,0);EditText title=new EditText(this);title.setHint("Başlık");title.setTextSize(16);title.setTypeface(null,Typeface.BOLD);title.setSingleLine(true);title.setText(e==null?"":titleOf(e.note));form.addView(title);EditText detail=new EditText(this);detail.setHint("Açıklama");detail.setTextSize(13);detail.setMinLines(2);detail.setText(e==null?"":detailOf(e.note));form.addView(detail);Button date=new Button(this);form.addView(date);EditText time=new EditText(this);time.setHint("Saat (örn. 14:30) — boşsa alarm yok");time.setTextSize(14);time.setSingleLine(true);time.setInputType(InputType.TYPE_CLASS_DATETIME|InputType.TYPE_DATETIME_VARIATION_TIME);if(e!=null&&!e.remindAt.isEmpty())time.setText(timeOnly(e.remindAt));form.addView(time);Calendar c=Calendar.getInstance();String initial=e!=null?e.date:forcedDay;if(initial!=null&&!initial.isEmpty())try{c.setTime(new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(initial));}catch(Exception ignored){}final String[] day={fmt(c,"yyyy-MM-dd")};date.setText("📅 "+dayMonth(day[0]));date.setOnClickListener(v->new DatePickerDialog(this,(z,y,m,dd)->{c.set(y,m,dd);day[0]=fmt(c,"yyyy-MM-dd");date.setText("📅 "+dayMonth(day[0]));},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show());AlertDialog dlg=new AlertDialog.Builder(this).setTitle(e==null?"Yeni Not":"Düzenle").setView(form).setNegativeButton("VAZGEÇ",null).setPositiveButton("KAYDET",null).create();dlg.setOnShowListener(x->dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String bas=title.getText().toString().trim(),det=detail.getText().toString().trim(),tm=time.getText().toString().trim();if(bas.isEmpty()){show("Başlık boş olamaz.");return;}if(!tm.isEmpty()&&!tm.matches("([01]?\\d|2[0-3]):[0-5]\\d")){show("Saati 14:30 şeklinde yazın.");return;}if(!tm.isEmpty()&&tm.length()==4)tm="0"+tm;String note=pack(category,bas+(det.isEmpty()?"":"\n"+det));String rem=tm.isEmpty()?"":day[0]+" "+tm;dlg.dismiss();if(e==null)save(day[0],note,rem);else update(e.id,day[0],note,rem);}));dlg.show();}
 private void renderCalendar(){if(body.getChildCount()>2)body.removeViews(2,body.getChildCount()-2);CalendarView cv=new CalendarView(this);cv.setFirstDayOfWeek(Calendar.MONDAY);body.addView(cv,new LinearLayout.LayoutParams(-1,-2));TextView dayTitle=t("",15,true);body.addView(dayTitle);ScrollView sc=new ScrollView(this);list=v();sc.addView(list);body.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Calendar c=Calendar.getInstance();if(calendarDay.isEmpty())calendarDay=fmt(c,"yyyy-MM-dd");showCalendarDay(dayTitle);cv.setOnDateChangeListener((view,y,m,d)->{calendarDay=String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d);showCalendarDay(dayTitle);});}
 private void showCalendarDay(TextView title){title.setText("📅 "+dayMonth(calendarDay));list.removeAllViews();int n=0;for(Api.Entry e:cache){if(!e.date.equals(calendarDay))continue;if(cat(e)==3&&!n3Unlocked)continue;if(archive?!visibleArchive(e):!visibleMain(e))continue;n++;list.addView(entryRow(e),rowParams());}if(n==0)list.addView(t("Bu gün için kayıt yok.",13,false));}
 private int cat(Api.Entry e){return e.note.startsWith(M2)?2:e.note.startsWith(M3)?3:1;} private String clean(String n){return n.startsWith(M2)||n.startsWith(M3)?n.substring(2):n;} private String pack(int c,String n){return c==2?M2+n:c==3?M3+n:n;} private String titleOf(String n){n=clean(n);int p=n.indexOf('\n');return(p<0?n:n.substring(0,p)).trim();} private String detailOf(String n){n=clean(n);int p=n.indexOf('\n');return p<0?"":n.substring(p+1).trim();}
 private void load(){if(token().isEmpty()){pairDialog();return;}new Thread(()->{try{List<Api.Entry>a=Api.agenda(token());runOnUiThread(()->{cache=a;if(page==4)buildPage();else render(a);});}catch(Exception e){runOnUiThread(()->show("Ajanda alınamadı: "+e.getMessage()));}}).start();} private void save(String d,String n,String r){new Thread(()->{try{Api.addEntry(token(),d,n,r);runOnUiThread(this::load);}catch(Exception e){runOnUiThread(()->show("Kaydedilemedi: "+e.getMessage()));}}).start();} private void update(int id,String d,String n,String r){new Thread(()->{try{Api.updateEntry(token(),id,d,n,r);runOnUiThread(this::load);}catch(Exception e){runOnUiThread(()->show("Güncellenemedi: "+e.getMessage()));}}).start();} private void archive(Api.Entry e,boolean a){new Thread(()->{try{Api.archive(token(),e.id,a);runOnUiThread(this::load);}catch(Exception x){runOnUiThread(()->show(x.getMessage()));}}).start();}
 private void delete(Api.Entry e){new AlertDialog.Builder(this).setTitle("Notu Sil").setMessage("Bu not silinsin mi?").setNegativeButton("HAYIR",null).setPositiveButton("SİL",(d,w)->new Thread(()->{try{Api.deleteEntry(token(),e.id);runOnUiThread(this::load);}catch(Exception x){runOnUiThread(()->show(x.getMessage()));}}).start()).show();}
 private void pinDialog(){String saved=getSharedPreferences(PREF,MODE_PRIVATE).getString("n3_pin","");EditText pin=new EditText(this);pin.setHint(saved.isEmpty()?"4 haneli PIN belirleyin":"PIN'inizi girin");pin.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);AlertDialog d=new AlertDialog.Builder(this).setTitle("NOT 3 - Özel").setView(pin).setNegativeButton("VAZGEÇ",null).setPositiveButton(saved.isEmpty()?"PIN OLUŞTUR":"AÇ",null).create();d.setOnShowListener(z->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(x->{String s=pin.getText().toString().trim();if(s.length()!=4){show("4 haneli PIN girin.");return;}String h=hash(s);if(saved.isEmpty())getSharedPreferences(PREF,MODE_PRIVATE).edit().putString("n3_pin",h).apply();else if(!saved.equals(h)){show("PIN yanlış.");return;}n3Unlocked=true;page=3;d.dismiss();buildPage();load();}));d.show();}
 private String hash(String s){try{byte[]b=MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8"));StringBuilder x=new StringBuilder();for(byte q:b)x.append(String.format(Locale.US,"%02x",q));return x.toString();}catch(Exception e){return s;}}
 private boolean connected(){if(!token().isEmpty())return true;pairDialog();return false;} private void pairDialog(){if(list==null)return;list.removeAllViews();list.addView(t("Site ajandanızla bağlantı yapın.",15,true));Button b=new Button(this);b.setText("SİTEYE BAĞLAN");b.setOnClickListener(v->showCodeDialog());list.addView(b);} private void showCodeDialog(){EditText code=new EditText(this);code.setHint("6 haneli kod");code.setInputType(InputType.TYPE_CLASS_NUMBER);AlertDialog d=new AlertDialog.Builder(this).setTitle("AJANDAM'ı Bağla").setView(code).setNegativeButton("VAZGEÇ",null).setPositiveButton("BAĞLA",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String c=code.getText().toString().trim();if(c.length()!=6){show("6 haneli kodu girin.");return;}new Thread(()->{try{String tok=Api.pair(c,"AJANDAM");getSharedPreferences(PREF,MODE_PRIVATE).edit().putString("token",tok).apply();runOnUiThread(()->{d.dismiss();startServiceNow();load();});}catch(Exception e){runOnUiThread(()->show("Bağlantı olmadı: "+e.getMessage()));}}).start();}));d.show();}
 private void show(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();} private String token(){return getSharedPreferences(PREF,MODE_PRIVATE).getString("token","");} private LinearLayout v(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);return x;} private TextView t(String s,int z,boolean b){TextView x=new TextView(this);x.setText(s);x.setTextSize(z);x.setTextColor(Color.BLACK);if(b)x.setTypeface(null,Typeface.BOLD);x.setPadding(5,3,5,3);return x;} private String fmt(Calendar c,String p){return new SimpleDateFormat(p,Locale.US).format(c.getTime());} private void startServiceNow(){Intent i=new Intent(this,SyncService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);} private void requestPermissionsIfNeeded(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},20);}
}
